        summary="契約社員のトラック運転手と正社員との間の各種手当の相違が争われた事案。最高裁は、労働契約法20条が私法上の効力を有し違反する部分は無効となるとしつつ、正社員の労働条件がそのまま適用されるわけではないとし、手当ごとに趣旨を検討して判断した。",
